  "pr.rates_esi": "Employee 0.75% and employer 3.25% of wages, each rounded up to the next rupee (Social Security (Central) Rules, 2026, rule 19). Wage limit ₹21,000 a month: check the current limit on the ESIC site. No employee share when the daily wage is ₹176 or less (ESIC contribution page).",
