  "it.basis": "बे हिसाबफोरा मा बेसेनआव ({d} सिम)",
  "it.b1": "रेट ({d} सिम), टेक्स बोसोर 2026-27: गोदान रिजिमआव ₹4 लाख सिम गैया, ₹8 लाख सिम 5%, ₹12 लाख सिम 10%, ₹16 लाख सिम 15%, ₹20 लाख सिम 20%, ₹24 लाख सिम 25%, बेनिख्रुइ बांसिनाव 30%; ₹12 लाख सिम आयआव टेक्स होनो नाङा बादि रिबेट, बेनि गोजौसोयाव मार्जिनेल रिलिफ; सेलारिआव ₹75,000 स्टेन्डार्ड डिडाक्सन। गोजाम रिजिम: ₹2.5 लाख सिम गैया (60 आव ₹3 लाख, 80 आव ₹5 लाख), ₹5 लाख सिम 5%, ₹10 लाख सिम 20%, बेनिख्रुइ बांसिनाव 30%; ₹5 लाख सिम ₹12,500 रिबेट; स्टेन्डार्ड डिडाक्सन ₹50,000। बेफोरा सेलारि स्लिप टुलआ सिगांनिफ्रायनो बाहायनाय रेट; बे बिल्डआव Finance Act निफ्राय फिन फरायाखै, बेनिखायनो बिसोरखौ नाय।",
  "it.b2": "एडभान्स टेक्स (Income-tax Act 2025, सेक्सन 403 निफ्राय 408): TDS नि उनाव टेक्सआ ₹10,000 एबा बेनिख्रुइ बांसिन जाब्ला होनांगौ; 15 June सिम 15%, 15 September सिम 45%, 15 December सिम 75%, 15 March सिम गासै; प्रिजाम्पटिभ टेक्सपेयारआ 15 March सिम गासै होयो; 31 March सिम होनाय पेमेन्टखौ बे बोसोरनि थाखाय सानो; बिजिनेस आय गैयि 60 एबा बेनिख्रुइ बांसिन बैसोनि रेसिडेन्टआ रेहाइ मोनो।",
  "it.b3": "सुद: सेक्सन 424 (गोजाम 234B) आ टेक्सनि 90% निख्रुइ खम होब्ला खम जानाय रांआव मोनफ्रोम दान एबा दाननि बाहागोआव 1%; सेक्सन 425 (गोजाम 234C) आ गिबि मोनथाम किस्तिनि मोनफ्रोमनि खम जानाय रांआव 3% (15 June सिम 12% आरो 15 September सिम 36% होब्ला गैया) आरो March नि खम जानाय रांआव 1%।",
  "it.b4": "गोजौनि सेक्सनफोरखौ 15 Nov 2026 आव Income Tax Department नि वेबसाइटआव (incometaxindia.gov.in) दंनाय अफिसियेल टेक्स्टजों सोदोब सोदोब नायबाय। छापायनाय Act आ फैसला लागोन।",
  "it.b5": "बहिनि लाभआ टेक्स लाजाथाव लाभ नङा: Act बादि डेप्रिसिएसन, मानि जायि खरच आरो प्रिजाम्पटिभ नियमफोरा बेखौ सोलायो। बे प्लेन आरो डेटा सिटखौ नोंथांनि एकाउन्टेन्टनो हो।",
  "it.b6": "हिसाब खालामा: सारचार्ज, खास रेटआव केपिटेल गेइन, बिदेसि टेक्स रिलिफ, नाबालिगनि आयआव टेक्स, आरो लेट फाइलिंनि सुद।",
