  "it.formd_ITR-1": "सेलारि एबा पेन्सन, नैसे सिम नो सम्पत्ति आरो सुद बादि गुबुन फुंखा दंनाय, आरो ₹50 लाख सिम गासै आय दंनाय रेसिडेन्ट मानसिनि थाखाय।",
