  "it.w_nonres": "रेसिडेन्ट नङै मानसिआ ITR-1 एबा ITR-4 बाहायनो हाया।",
  "it.w_over50": "₹50 लाखनिख्रुइ बांसिन गासै आय जाब्ला ITR-1 आरो ITR-4 बाहायनो हाया।",
  "it.w_capgain": "फिसा लिस्टेड-सेयार सिमा बाहायै गुबुन केपिटेल गेइनआव ITR-2 एबा ITR-3 नांगौ।",
  "it.w_houses": "नैसेनिख्रुइ बांसिन नो सम्पत्ति जाब्ला ITR-1 आरो ITR-4 बाहायनो हाया।",
  "it.w_foreign": "बिदेसि सम्पत्ति एबा बिदेसि आयआव ITR-2 एबा ITR-3 नांगौ।",
  "it.w_director": "कम्पानिनि डाइरेक्टारआ ITR-1 एबा ITR-4 बाहायनो हाया।",
  "it.w_unlisted": "आनलिस्टेड सेयार थाब्ला ITR-1 आरो ITR-4 बाहायनो हाया।",
  "it.w_agri": "₹5,000 निख्रुइ बांसिन आबादनि आय जाब्ला ITR-1 आरो ITR-4 बाहायनो हाया।",
  "it.w_loss": "केरि फरवार्ड एबा सेट अफ खालामनो खहा (लस) थाब्ला ITR-2 एबा ITR-3 नांगौ।",
  "it.w_esop": "मालिकनि सेयारआव डेफार्ड टेक्स थाब्ला ITR-2 एबा ITR-3 नांगौ।",
  "it.w_crypto": "भार्चुयेल डिजिटेल एसेटनिफ्राय आयआव ITR-2 एबा ITR-3 नांगौ।",
  "it.w_huf": "ITR-1 आ खालि मानसिनि थाखायसो; बिजिनेस आय गैयि HUF आ ITR-2 फाइल खालामो।",
  "it.w_pres2": "नोंथांनि गुबुन फिननायफोरा ITR-4 खौ बाहायनो होया, बेनिखायनो बिजिनेस आयआ ITR-3 आव थांयो।",
  "it.w_pres": "आसान गुबुन आयजों प्रिजाम्पटिभ बिजिनेस आयआ ITR-4 आव गोरोबो।",
  "it.w_simple": "सिमानि सिङाव खालि सेलारि, नो सम्पत्ति आरो सुद जाब्ला ITR-1 आव गोरोबो।",
  "it.n_forms": "सर्तफोरा 31 March 2026 आव जोबनाय बोसोरनि थाखाय नटिफाइ खालामनाय रिटार्न बादि (टेक्स पर्टालफोरा बुङो बादि, ITR-1 आरो ITR-4 आव दा नैसे सिम नो सम्पत्ति मोनो)। टेक्स बोसोर 2026-27 नि रिटार्नफोरखौ Income-tax Rules, 2026 आव दासिम नटिफाइ खालामाखै: फाइल खालामनायनि सिगां सोर बाहायनो हाया बुङा फर्मनि गावनि लिस्ट फराय।",
  "it.n_ltcg": "लिस्टेड सेयार एबा इक्युइटि फान्डनि फिसा लंग-टार्म गेइनखौ माखासे बोसोरआव ITR-1 आरो ITR-4 आव होनाय जादोंमोन; 2026-27 नि थाखाय बेखौ थार खालामाखै, बेनिखायनो ITR-2 आ रैखाथि गोनां सायखनाय आरो फर्मनि गावनि लिस्टआ फैसला लायो।",
  "it.n_ae": "सेक्सन 44AE (मालनि गाड़ि) नि गावनि सर्त दं; प्रिजाम्पटिभ फर्म बाहायनायनि सिगां बिसोरखौ नाय।",
  "it.n_tax": "प्रिजाम्पटिभ रेटनिख्रुइ खम लाभ बुङोब्ला बहि नांगौ आरो अडिट नांगौ हागौ: अब्ला रिटार्नआ ITR-3।",
