  "ca.t": "आंनि एकाउन्टेन्टनि थाखाय फाइल",
  "ca.intro": "मोनसे बिजिनेस आरो समाखौ मोनसे खालि फरायनो हानाय फाइलआव (.nsca) दोनो। बेखौ नोंथांनि एकाउन्टेन्टनो WhatsApp एबा इमेलजों दैथि। बिथाङा बेखौ ca.niveshsahayak.in आव खेवो, बहि फरायो, सोंथि दाजाबो आरो नोंथांनो कमेन्ट फिन दैथियो।",
  "ca.notlive": "बेयो फाइल होनाय, लाइभ सेयार लगिन नङा। नोंथाङा फाइल बानायनाय समाव बहिआ माबादि थादोंमोन, नोंथांनि एकाउन्टेन्टआ बेबादिनो नुयो। लाइभ लगिननि थाखाय नोंथांनि बहि दोननो मोनसे सार्भार नांगौ, आरो Nivesh Sahayak नि सार्भार गैया: नोंथांनि बहिआ नोंथांनि डिभाइसआवसो थायो। गोदान एन्ट्रिनि थाखाय गोदान फाइल बानाय।",
  "ca.what": "मा थांगोन",
