  "ca.codeh": "बे कोडखौ नोंथांनि खौरांआव दैथि, एबा फोनआव फराय। नोंथांनि एकाउन्टेन्टआ बेखौ फाइलआ दिन्थिनाय कोडजों रुजु खालामो, बेनिखायनो लामायाव सोलायनाय फाइलखौ मिथिनो हायो।",
