  "ca.cT": "CA नि कमेन्ट",
  "ca.cIntro": "नोंथांनि एकाउन्टेन्टआ सोंथि आरो कमेन्टनि मोनसे फिसा फाइल (.nsca-comments) फिन दैथियो। मोनफ्रोम सोंथिखौ बेनि एन्ट्रिनि आगसियाव नायनो बेखौ बेयाव लोड खालाम। फिन हो, बन्द मार्क खालाम, आरो फिन दैथिनो फाइलखौ फिन सेभ खालाम।",
