  "ca.party": "पार्टि",
  "ca.screen": "स्क्रिन",
  "ca.general": "सरासरि कमेन्ट",
  "cv.h1": "एकाउन्टेन्ट भिउआर: नोंथांनि क्लाइन्टआ दैथिनाय बहि फाइलखौ खेव",
  "cv.intro": "नोंथांनि क्लाइन्टआ मोनसे समानि बहिखौ मोनसे फाइलआव दोनो आरो नोंथांनो WhatsApp एबा इमेलजों दैथियो। बेखौ बेयाव खेव आरो फराय: बाकि, पार्टि, लेजार, डे बुक, GST हिसाब, फाइनेल एकाउन्ट आरो गासै डकुमेन्ट। नागिर आरो फिल्टार खालाम, जायखि एन्ट्रियाव सोंथि सों, आरो नोंथांनि कमेन्टफोरखौ मोनसे फिसा फाइल बादि फिन दैथि। थामलाइ, लगिन नांया, आरो जेबो आपलड जाया: फाइलखौ नोंथांनि ब्राउजारनि सिङावसो फरायो।",
  "cv.drop": ".nsca फाइलखौ बेयाव हो",
  "cv.choose": "फाइल सायख",
  "cv.dropnote": "फाइलआ बे डिभाइसआवसो थायो। बेयाव जेबो सेभ जाया आरो बेयाव नोंथाङा नोंथांनि क्लाइन्टनि बहिखौ सोलायनो हाया।",
  "cv.nav.home": "सारांस",
  "cv.docs": "डकुमेन्टफोर",
  "cv.day": "डे बुक",
  "cv.fin": "फाइनेल एकाउन्ट",
  "cv.gst": "GST हिसाब",
  "cv.cT": "सोंथि आरो कमेन्ट",
  "cv.how.h": "बेयो माबोरै खामानि मावो",
  "cv.how.1": "नोंथांनि क्लाइन्टआ Nivesh Sahayak खेवो, आंनि डेटा, एकाउन्टेन्टनो दैथि आव थांयो, आरो मोनसे बिजिनेस आरो समानि थाखाय \"Make a file for my accountant\" सायखो।",
  "cv.how.2": "बिथाङा नोंथांनो फाइल (.nsca जों जोबनाय) आरो मोनसेनो खौरांआव मोनसे फिसा नायनाय कोड दैथियो।",
  "cv.how.3": "नोंथाङा बे पेजआव फाइलखौ खेवो। पेजआ फाइलआ सोलायाखै नामा बुङो आरो नोंथांनि क्लाइन्टआ होनाय नायनाय कोडखौ रुजु खालामनो लिरहोयो।",
  "cv.how.4": "बहि फराय, नागिर, आरो जायखि डकुमेन्ट, डे-बुक एन्ट्रि एबा स्क्रिनआव \"Add a query or comment\" प्रेस खालाम। नोंथाङा लिरनाय गासैबो बे ब्राउजारआवसो थायो।",
  "cv.how.5": "जोबब्ला, \"Queries and comments\" खेव आरो फिसा .nsca-comments फाइलखौ फिन दैथि। नोंथांनि क्लाइन्टआ बेखौ लोड खालामो आरो मोनफ्रोम सोंथिखौ एन्ट्रिनि आगसियाव नुयो। बिथाङा फिन होनो हायो, आरो नोंथाङा फिननायफोरखौ बेयाव लोड खालामनो हायो।",
  "cv.live.h": "फाइल होनाय, लाइभ लगिन नङा",
  "cv.live.p": "बेयो फाइल होनाय। नोंथाङा नोंथांनि क्लाइन्टनि एकाउन्टआव लगिन खालामा आरो बिथाङा उनाव खालामनाय सोलायनायफोर नुया। लाइभ सेयार लगिननि थाखाय बहि दोननो मोनसे सार्भार नांगौ, आरो Nivesh Sahayak नि सार्भार गैया: बहिआ नोंथांनि क्लाइन्टनि डिभाइसआवसो थायो। गोदान समा एबा सुधारनायनि उनाव, नोंथांनि क्लाइन्टनिफ्राय गोदान फाइल बिनाय।",
  "cv.safe.h": "फाइलआव मा दं, आरो मा गैया",
  "cv.safe.p": "नोंथांनि क्लाइन्टआ मा थांगोन बेखौ टिक होयो। सरासरि फाइलआव मोनसे बिजिनेसनि समा जोबनाय सिम एन्ट्रि, पार्टि आरो आइटेम थायो। कोटेसन आरो अर्डार, सेलारि आरो स्टाफनि रेकर्ड, फोन नम्बर आरो इमेल ठिकाना, आरो बिजिनेसनि बेंक एकाउन्टनि बिबुंफोरा नोंथांनि क्लाइन्टआ टिक होयाब्ला थाया। सावगारि, PIN आरो बेकआप सेटिं जेबो समाव थाया। फाइलआव चेकसाम थायो, बेनिखायनो जायखि सोलायनाया बे पेजआव दिन्थियो। फाइलखौ सोलायनानै चेकसामखौ फिन हिसाब खालामग्राखौ चेकसामआ होबथानो हाया, बेनिखायनो नोंथांनि क्लाइन्टआ आलादा दैथिनाय नायनाय कोडजों रुजु खालाम।",
  "cv.readonly": "बेयो मोनसे फाइलनि खालि फरायनो हानाय भिउ: बेयाव जेबो सोलायनो एबा सेभ खालामनो हाया।",
  "cv.notfile": "बेयो Nivesh Sahayak नि एकाउन्टेन्ट फाइल (.nsca) नङा।",
  "cv.iscomments": "बेयो कमेन्ट फाइल। गिबियाव बहि फाइल (.nsca) खेव, बेनि उनाव \"Queries and comments\" निफ्राय कमेन्ट लोड खालाम।",
  "cv.newer": "बे फाइलखौ गोदान भार्सनआ बानायदों। बे पेजखौ फिन लोड खालाम आरो फिन नाजा।",
  "cv.nostore": "नोंथांनि कमेन्टफोरखौ बे ब्राउजारआव दोननो हायाखै। दानो कमेन्ट फाइल सेभ खालाम।",
