  "cv.cIntro": "नोंथांनि सोंथि आरो कमेन्टफोर। बिसोरा बे फाइलनि थाखाय बे ब्राउजारआव थायो। \"Save the comments file\" प्रेस खालाम आरो नोंथांनि क्लाइन्टनो दैथि; बिथाङा बेखौ लोड खालामो आरो मोनफ्रोम सोंथिखौ एन्ट्रिनि आगसियाव नुयो।",
