  "hm.h.recv.low": "रांआ ग्राहकफोरनि आखायाव गोलाव समा थायो। गिबियाव सबायनिख्रुइ गोजाम बिलफोरखौ ला आरो गोदान अर्डारनि सिगां बाहागो पेमेन्ट सों।",
  "hm.h.recv.rule": "ग्राहकफोरा दासिम होनांगौ रांखौ जोबथा आबुं 3 दाननि सानफ्रोमनि फान्नायजों राननाय। 30 सान एबा खम जाब्ला 100, 90 सान एबा बांसिन जाब्ला 0।",
