  "hm.rm.l1": "मोनसे वेब पेजआ बन्द थाब्ला सोलिनो हाया, आरो बे Appनि उनाव पुस खौरां दैथिनो जेबो सार्भार गैया। बेनिखायनो Appनिफ्राय गोसोखांहोनायआ खालि नोंथाङा App खेवब्लासो नुयो।",
  "hm.rm.l2": "गासैबो नोंथांनि डिभाइसआव हिसाब जायो, बेनिखायनो इन्टारनेट गैयाब्लाबो खामानि मावो। नोंथांनि बिजिनेसनि सोमोन्दै जेबो जायगायाव दैथिया।",
  "hm.rm.l3": "बादआव दोननो हायि तारिखफोरनि थाखाय केलेन्डार फाइल बाहाय: नोंथांनि फोननि केलेन्डारआ गावनो रिं होयो। बेयो दिनैनि मोनसे सावगारि, बेनिखायनो गोदान बिल लिरनायनि उनाव गोदान फाइल बानाय।",
  "hm.rm.l4": "इनस्टल खालामनाय Appआव, नोंथांनि फोनआ मानि होब्ला, बेनि आइकनआव नम्बरआ बेसेबां गोख्रों मुवा दं दिन्थियो।",
